// The case library bundled with the app (generated by scripts/build-missions.ts),
// so cases play offline. Newer versions arrive like any other content.
import bundled from '../../../content/missions/dist/missions.json';
import { Mission, type GradeBand } from '@/content/schemas';

export interface CaseFile {
  id: string;
  version: number;
  gradeBands: GradeBand[];
  standardIds: string[];
  mission: Mission;
}

const ALL: CaseFile[] = (bundled as { id: string; version: number; grade_bands: GradeBand[]; standard_ids: string[]; data: unknown }[])
  .map((m) => ({ id: m.id, version: m.version, gradeBands: m.grade_bands, standardIds: m.standard_ids, mission: Mission.parse(m.data) }));

export const caseFile = (id: string) => ALL.find((c) => c.id === id);

/** Cases for a grade band; the hand-written sample case is listed first for its band. */
export function casesFor(band: GradeBand): CaseFile[] {
  return ALL.filter((c) => c.gradeBands.includes(band)).sort((a, b) => Number(a.id.startsWith('mission:g')) - Number(b.id.startsWith('mission:g')));
}
